    "Visitor at work",
    [120, 200],
    [60, 192],
    1.05,
    visitorSeated,
    ["person", "work", "desk"],
  ),
  T(
    "person-seated",
    "At work, from behind",
    [120, 220],
    [60, 212],
    1.05,
    personSeated,
    ["person", "work", "focus"],
  ),
