export interface Scene {
  name: string
  /** The accessible name of a drawing of this scene. */
  label: string
  size: [number, number]
  compose: (seed: string, hand: HandName, take: number) => Sheet
}

const BUILT_IN = {
  room: {
    name: "Listening room",
    label:
      "A record shop floor: browser bins, records face out on the wall and the counter with its till",
    size: [W, H],
    compose: room,
  },
  studio: {
    name: "Studio",
    label:
      "A studio with a desk, a screen, sticky notes and a person with a coffee",
    size: [W, H],
    compose: studio,
  },
  bistro: {
    name: "Bistro",
    label:
      "A bistro table for two with wine, a candle and a plate, under a pendant lamp",
    size: [W, H],
    compose: bistro,
  },
  work: {
    name: "At work",
    label:
      "Someone at work at a desk under a window, seen from behind on an office chair",
    size: [W, H],
    compose: work,
  },
} satisfies Record<string, Scene>

/** A scene's name: one of the kit's, or one a project added with defineScene. */
export type SceneName = keyof typeof BUILT_IN | (string & {})

export const SCENES: Record<string, Scene> = { ...BUILT_IN }

/** Add a scene, or replace one with the same name, so drawing({ scene }) and <Drawing scene> find it. */
export function defineScene(name: string, scene: Scene) {
  SCENES[name] = scene
}

// Shapes every object builds from: the oblique box, the padded box, a band across a rounded box, a drum seen from
// above, the upright cylinder, a cup's handle, a leafy sprig and lines of scribbled text. Objects take their own
// depth angle from the seed, so neighbours disagree a little about perspective.
import { add, arc, deg, dist, lerp, type Point } from "./geometry"
import type { Stream } from "./seed"
import type { Sheet } from "./layers"
import { HANDS, type Pen } from "./stroke"

/** Where "back" is for one object: up and to the right, at a seeded angle and depth. */
export function depth(r: Stream): Point {
  const a = (30 + r.signed() * 12) * deg
  const f = 0.5 + r.signed() * 0.1
  return [Math.cos(a) * f, -Math.sin(a) * f]
}

export interface Box {
  w: number
  d: number
  o: Point
  /** A point on the front face: u runs left to right, v bottom to top. */
  front(u: number, v: number): Point
  /** A point on the top face: u runs left to right, v front to back. */
  top(u: number, v: number): Point
}

/** An oblique box: front face w × h with its bottom-left corner at `at`, receding d along `o`. */
export function box(
  s: Sheet,
  p: Pen,
  o: Point,
  at: Point,
  w: number,
  h: number,
  d: number,
): Box {
  const [x, y] = at
  const A: Point = [x, y]
  const B: Point = [x + w, y]
  const C: Point = [x + w, y - h]
  const D: Point = [x, y - h]
  const back = (q: Point) => add(q, o, d)
  const [B2, C2, D2] = [back(B), back(C), back(D)]
  // The outline in one closed stroke, then the three inner edges meeting it at C. Their free ends stop short by about
  // half a run-past, so the pen lands on the outline instead of poking through it, as a careful hand draws a box.
  const outline = [A, B, B2, C2, D2, D]
  const tuck = (from: Point, to: Point) =>
    lerp(to, from, (HANDS[p.hand].over * 0.4) / (dist(from, to) || 1))
  s.blank(p.shape(outline))
  s.stroke(p.shape(outline))
  s.stroke(p.path([tuck(C, D), C, tuck(C, C2)]))
  s.stroke(p.line(tuck(B, C), tuck(C, B)))
  return {
    w,
    d,
    o,
    front: (u, v) => [x + w * u, y - h * v],
    top: (u, v) => add(lerp(D, C, u), o, d * v),
  }
}

/**
 * A padded box, as an armchair's arm, back or cushion: an oblique box whose front face has rounded top corners, so its
 * top rolls over instead of meeting the front at an edge. Same arguments as `box`, plus the corners' radius.
 */
export function pad(
  s: Sheet,
  p: Pen,
  o: Point,
  at: Point,
  w: number,
  h: number,
  d: number,
  rad: number,
): Box {
  const [x, y] = at
  const back = (q: Point) => add(q, o, d)
  const left: Point = [x + rad, y - h + rad]
  const right: Point = [x + w - rad, y - h + rad]
  // Where a line along `o` grazes the top-left roll: the left edge of the top.
  const len = Math.sqrt(o[0] * o[0] + o[1] * o[1]) || 1
  const graze = Math.atan2(-o[0] / len, o[1] / len) / deg + 360
  const roll: Point[] = [
    ...arc(left, rad, rad, graze, 270, 4),
    ...arc(right, rad, rad, 270, 360, 6),
    [x + w, y],
  ]
  // As in `box`: the outline in one closed stroke, then the front's roll and right side as one run that starts on the
  // outline and stops just short of the bottom corner.
  const outline: Point[] = [
    [x, y],
    ...arc(left, rad, rad, 180, graze, 4),
    ...roll.map(back),
    [x + w, y],
  ]
  const end = roll.length - 1
  const pull = (HANDS[p.hand].over * 0.4) / (h - rad || 1)
  roll[end] = lerp(roll[end] as Point, roll[end - 1] as Point, pull)
  s.blank(p.shape(outline))
  s.stroke(p.shape(outline))
  s.stroke(p.path(roll))
  return {
    w,
    d,
    o,
    front: (u, v) => [x + w * u, y - h * v],
    top: (u, v) => add([x + rad + (w - 2 * rad) * u, y - h], o, d * v),
  }
}

/**
 * A rounded rectangle cut across `cut` below its top, as a browser's tab bar or a camera's top: the band above the cut
 * in one closed stroke, the rest in one run whose ends carry on up the band's sides, so the cut meets both sides.
 * Blank the outline first. (x, y) is the top-left corner.
 */
export function banded(
  s: Sheet,
  p: Pen,
  x: number,
  y: number,
  w: number,
  h: number,
  rad: number,
  cut: number,
) {
  const c = (cx: number, cy: number, a0: number) =>
    arc([cx, cy], rad, rad, a0, a0 + 90, 5)
  s.stroke(
    p.shape([
      [x, y + cut],
      ...c(x + rad, y + rad, 180),
      ...c(x + w - rad, y + rad, 270),
      [x + w, y + cut],
    ]),
  )
  s.stroke(
    p.path([
      [x + w, y + cut],
      ...c(x + w - rad, y + h - rad, 0),
      ...c(x + rad, y + h - rad, 90),
      [x, y + cut],
    ]),
  )
}

/** An upright cylinder seen from a little above: `c` is the centre of its top. Returns its rims. */
export function cylinder(
  s: Sheet,
  p: Pen,
  c: Point,
  rx: number,
  ry: number,
  h: number,
) {
  const bottom: Point = [c[0], c[1] + h]
  s.blank(
    p.shape([
      ...arc(c, rx, ry, 180, 360, 12),
      ...arc(bottom, rx, ry, 0, 180, 12),
    ]),
  )
  s.stroke(p.ring(c, [rx, 0], [0, ry]))
  // The sides and the bottom in one run, starting and ending just under the rim so its run-on lands on it.
  const under = c[1] + HANDS[p.hand].over * 0.4
  s.stroke(
    p.path([
      [c[0] - rx, under],
      ...arc(bottom, rx, ry, 180, 0, 12),
      [c[0] + rx, under],
    ]),
  )
  return { top: c, bottom }
}

/** A handle on the side of a cup or jug, from y0 to y1 at x, bulging by `reach`. */
export function handle(
  s: Sheet,
  p: Pen,
  x: number,
  y0: number,
  y1: number,
  reach: number,
) {
  s.stroke(p.path(arc([x, (y0 + y1) / 2], reach, (y1 - y0) / 2, -90, 90, 10)))
}

/** Short wavy lines of text, for menus, notes and screens. */
export function scribble(
  s: Sheet,
  p: Pen,
  r: Stream,
  x: number,
  y: number,
  w: number,
  lines: number,
  gap = 7,
) {
  for (let i = 0; i < lines; i++) {
    const len =
      w * (i === lines - 1 ? r.between(0.35, 0.7) : r.between(0.75, 1))
    const pts = Array.from({ length: 6 }, (_, j): Point => [
      x + (len * j) / 5,
      y + i * gap + (j % 2 ? 0.8 : -0.8),
    ])
    s.stroke(p.path(pts))
  }
}

/**
 * Anything round seen a little from above (a pot's rim, a lampshade, a lamp's foot): its top rim centred on `c` and
 * its bottom rim `h` below. The back of the top rim goes first and starts and ends a little way down inside the front,
 * so the front, one closed stroke, covers where the pen runs past it. `inside` draws what stands inside the rim
 * (stems, a cactus) between the two, so the front hides where it goes in.
 */
export function drum(
  s: Sheet,
  p: Pen,
  c: Point,
  [rt, rb, h, e]: [number, number, number, number],
  inside?: () => void,
  wash = false,
) {
  s.blank(p.shape(arc(c, rt, e, 0, 360, 24)))
  const tuck = (f: number) => add(c, [f * rt * 0.9, e * 0.6])
  s.stroke(p.path([tuck(-1), ...arc(c, rt, e, 180, 360, 12), tuck(1)]))
  inside?.()
  const front = [
    ...arc(c, rt, e, 180, 0, 12),
    ...arc([c[0], c[1] + h], rb, (e * rb) / rt, 0, 180, 12),
  ]
  s.blank(p.shape(front))
  if (wash) s.wash(p.shape(front))
  s.stroke(p.shape(front))
}

/** A twig from a to b with small solid leaves along it in pairs and one at its tip, which covers the twig's end. */
export function sprig(s: Sheet, p: Pen, a: Point, b: Point, size: number) {
  s.stroke(p.line(a, b))
  const len = dist(a, b) || 1
  const blade = (at: Point, d: Point) => {
    const m: Point = [-d[1] * size * 0.24, d[0] * size * 0.24]
    const mid = add(at, d, size * 0.5)
    s.fill(p.shape([at, add(mid, m), add(at, d, size), add(mid, m, -1)]))
  }
  const [dx, dy] = [(b[0] - a[0]) / len, (b[1] - a[1]) / len]
  const n = Math.max(1, Math.floor(len / (size * 1.5)))
  for (let i = 1; i <= n; i++)
    for (const f of [-0.75, 0.75])
      blade(lerp(a, b, i / (n + 0.6)), [dx * 0.65 - dy * f, dy * 0.65 + dx * f])
  blade(b, [dx, dy])
}

// The pen. Every line is one thin monoline stroke with a slow hand wobble, drawn from a seed, so the same seed always
// draws the same line. Ported from the prototype in specimen/pen.js, with Patina's cross-engine rules: inputs are
// snapped before they decide a count or a random draw, and no ** or Math.pow.
import { dist, last, length, snap, type Point } from "./geometry"
import { pathOf } from "./path"
import { fork, prng, seedOf } from "./seed"

export type HandName = "calm" | "lively"

/**
 * How far a hand strays. amp: slow wobble in px; wave: its wavelength; tremor: fine shake; over: how far a line may
 * run past its end (a negative draw stops short); loop: the extra turn on a drawn circle, in radians.
 */
export const HANDS = {
  calm: { amp: 0.35, wave: 60, tremor: 0.08, over: 1.2, loop: 0.12 },
  lively: { amp: 1.1, wave: 40, tremor: 0.18, over: 4.5, loop: 0.45 },
} as const

/** Slow 1D noise along a line: random offsets at knots `wave` apart, eased between them. */
export function noise(
  rand: () => number,
  size: number,
  wave: number,
  amp: number,
) {
  const n = Math.ceil(snap(size / wave)) + 2
  const knots = Array.from({ length: n }, () => (rand() * 2 - 1) * amp)
  return (s: number) => {
    const t = Math.max(0, s) / wave
    const i = Math.min(Math.floor(t), n - 2)
    const u = (1 - Math.cos((t - i) * Math.PI)) / 2
    return (knots[i] as number) * (1 - u) + (knots[i + 1] as number) * u
  }
}

export type Sample = [number, number, number]

/** Points every `step` px along a polyline, with their distance from the start. */
export function resample(points: Point[], step: number): Sample[] {
  const first = points[0] as Point
  const out: Sample[] = [[first[0], first[1], 0]]
  let s = 0
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1] as Point
    const b = points[i] as Point
    const len = snap(dist(a, b))
    const n = Math.max(1, Math.round(len / step))
    for (let j = 1; j <= n; j++) {
      const f = j / n
      out.push([
        a[0] + (b[0] - a[0]) * f,
        a[1] + (b[1] - a[1]) * f,
        s + len * f,
      ])
    }
    s += len
  }
  return out
}

export interface Pen {
  hand: HandName
  /** The pen's own random stream, for choices an object makes while drawing. */
  next: () => number
  /** One straight stroke. */
  line(a: Point, b: Point): string
  /** A smooth open stroke through points. */
  path(points: Point[]): string
  /** A polygon drawn edge by edge, so its corners cross or fall short. */
  edges(points: Point[], closed?: boolean): string
  /** A closed outline in one stroke, for fills and blanks. */
  shape(points: Point[]): string
  /** A drawn ellipse (centre plus two axis vectors): the pen goes a little past where it started. */
  ring(c: Point, u: Point, v?: Point): string
  /** A closed ellipse outline, for solid discs. */
  disc(c: Point, u: Point, v?: Point): string
  /** Points round an ellipse from `from`, sweeping `turn` radians. */
  round(c: Point, u: Point, v: Point, from: number, turn: number): Point[]
}

/**
 * A pen with a hand. Each call draws the next stroke from the pen's own stream. Takes (line boil, settling) redraw
 * the same composition with another pen: a labelled fork per take, so take 0 is the drawing itself.
 */
export function pen(
  seed: string | number,
  handName: HandName = "lively",
  take = 0,
): Pen {
  const hand = HANDS[handName] ?? HANDS.lively
  const rand = prng(fork(seedOf(seed), take ? `pen:take:${take}` : "pen"))
  const between = (a: number, b: number) => a + rand() * (b - a)

  /**
   * Offset a polyline along its normals by slow wobble plus tremor. `closed` makes the offsets meet and centres them,
   * so a closed shape wobbles without growing or shrinking: on a small dot the slow wobble is nearly one offset all
   * the way round, which would otherwise make one eye twice the size of the other.
   */
  function trace(points: Point[], closed = false): Point[] {
    const pts = resample(
      points.map(([x, y]) => [snap(x), snap(y)]),
      3,
    )
    const size = last(pts)[2] || 1
    const slow = noise(rand, size, hand.wave * between(0.8, 1.25), hand.amp)
    const fine = noise(rand, size, 7, hand.tremor)
    const start = slow(0) + fine(0)
    const end = slow(size) + fine(size)
    const offs = pts.map(([, , s]) =>
      closed
        ? slow(s) + fine(s) - ((end - start) * s) / size
        : slow(s) + fine(s),
    )
    const mean = closed ? offs.reduce((t, o) => t + o, 0) / offs.length : 0
    return pts.map(([x, y], i) => {
      const a = pts[Math.max(0, i - 1)] as Sample
      const b = pts[Math.min(pts.length - 1, i + 1)] as Sample
      const len = length([b[0] - a[0], b[1] - a[1]]) || 1
      const off = (offs[i] as number) - mean
      return [x - ((b[1] - a[1]) / len) * off, y + ((b[0] - a[0]) / len) * off]
    })
  }

  /** Run the first and last segment on past their ends (or stop short), as a quick hand does. */
  function overshoot(points: Point[]): Point[] {
    const pts = points.map((p) => [p[0], p[1]] as Point)
    const extend = (p: Point, q: Point) => {
      const len = dist(p, q) || 1
      const o = between(-0.25, 1) * hand.over
      p[0] += ((p[0] - q[0]) / len) * o
      p[1] += ((p[1] - q[1]) / len) * o
    }
    extend(pts[0] as Point, pts[1] as Point)
    extend(last(pts), pts[pts.length - 2] as Point)
    return pts
  }

  function round(c: Point, u: Point, v: Point, from: number, turn: number) {
    const span = snap(length(u) + length(v))
    const n = Math.max(12, Math.round(snap((span * turn) / 4)))
    return Array.from({ length: n + 1 }, (_, i): Point => {
      const t = from + (turn * i) / n
      return [
        c[0] + u[0] * Math.cos(t) + v[0] * Math.sin(t),
        c[1] + u[1] * Math.cos(t) + v[1] * Math.sin(t),
      ]
    })
  }

  return {
    hand: handName,
    next: rand,
    line: (a, b) => pathOf(trace(overshoot([a, b]))),
    path: (points) => pathOf(trace(overshoot(points))),
    edges(points, closed = true) {
      const ring = closed ? [...points, points[0] as Point] : points
      let d = ""
      for (let i = 1; i < ring.length; i++)
        d += pathOf(trace(overshoot([ring[i - 1] as Point, ring[i] as Point])))
      return d
    },
    // The loop starts and ends halfway along its first edge: started in a corner, the two ends would be pushed off
    // along different normals and leave a spike where they meet.
    shape(points) {
      const first = points[0] as Point
      const [a, b] = [first, (points[1] ?? first) as Point]
      const mid: Point = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]
      return pathOf(trace([mid, ...points.slice(1), first, mid], true), true)
    },
    ring(c, u, v = [0, u[0]]) {
      const from = between(0, Math.PI * 2)
      const turn = Math.PI * 2 + between(0.3, 1) * hand.loop
      return pathOf(trace(round(c, u, v, from, turn)))
    },
    disc(c, u, v = [0, u[0]]) {
      const pts = round(c, u, v, between(0, Math.PI * 2), Math.PI * 2)
      return pathOf(trace([...pts.slice(0, -1), pts[0] as Point], true), true)
    },
    round,
  }
}
